{
  "findings": [
    {
      "check_id": "CKV_AWS_21",
      "title": "Ensure all data stored in the S3 bucket have versioning enabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "HIGH",
      "explanation": "Versioning is not enabled on the S3 bucket. Without versioning, accidental or malicious deletions or overwrites of objects cannot be recovered."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "Ensure the S3 bucket has access logging enabled",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "Access logging is not enabled for the S3 bucket. Without logging, it is difficult to track access patterns or detect unauthorized access."
    },
    {
      "check_id": "CKV_AWS_145",
      "title": "Ensure that S3 buckets are encrypted with KMS by default",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have server-side encryption enabled with a KMS key. This could lead to sensitive data being stored unencrypted."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "Ensure that S3 bucket has a Public Access block",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a Public Access Block configuration. This increases the risk of accidental public exposure of sensitive data."
    },
    {
      "check_id": "CKV2_AWS_61",
      "title": "Ensure that an S3 bucket has a lifecycle configuration",
      "resource": "aws_s3_bucket.cloudtrail_logs",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket does not have a lifecycle policy. Without lifecycle management, old or unused objects may accumulate, increasing storage costs."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket = "fleet-management-gps-tracking-system-cloudtrail-${random_string.bucket_suffix.result}"

  versioning {
    enabled = true
  }

  logging {
    target_bucket = "fleet-management-logs-bucket"
    target_prefix = "cloudtrail-logs/"
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        kms_master_key_id = "alias/aws/s3"
        sse_algorithm     = "aws:kms"
      }
    }
  }

  public_access_block_configuration {
    block_public_acls       = true
    block_public_policy     = true
    ignore_public_acls      = true
    restrict_public_buckets = true
  }

  lifecycle_rule {
    id      = "expire-old-logs"
    enabled = true

    expiration {
      days = 365
    }

    noncurrent_version_expiration {
      days = 30
    }
  }
}
",
  "fix_summary": "Enabled versioning, access logging, server-side encryption with KMS, public access block, and a lifecycle policy for the S3 bucket to address identified security misconfigurations."
}
